def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids); types = list(feats.types)
    labs = sorted(set(feats.stratum))
    Z0 = [np.ones(n)] + [np.array([s == l for s in feats.stratum], float) for l in labs[1:]]
    C = np.corrcoef(X.T); C = np.nan_to_num(C); A = np.abs(C)
    def fit(cols):
        M = np.column_stack(Z0 + [X[:, j[0]] * X[:, j[1]] if isinstance(j, tuple) else X[:, j] for j in cols])
        b = np.zeros(M.shape[1])
        for _ in range(30):
            eta = np.clip(M @ b, -30, 30); mu = 1 / (1 + np.exp(-eta)); w = mu * (1 - mu) + 1e-9
            H = M.T @ (M * w[:, None]) + 1e-6 * np.eye(M.shape[1])
            step = np.linalg.solve(H, M.T @ (y - mu)); b += step
            if np.max(np.abs(step)) < 1e-7: break
        mu = np.clip(1 / (1 + np.exp(-np.clip(M @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(mu) + (1 - y) * np.log(1 - mu)))
    def pv(l1, l0): return float(stats.chi2.sf(max(2 * (l1 - l0), 0), 1))
    deg = (A >= 0.6).sum(0) - 1
    hubs = [j for j in np.argsort(-deg) if types[j] == 'clinical' and deg[j] >= 3][:3]
    sel = []
    gates = [0.25 / p, 0.05 / p, 0.05 / p, 0.05 / p]
    for step in range(MAX_DRIVERS):
        adj = lambda j: [h for h in hubs if h != j and A[h, j] < 0.95 and all(A[h, s] < 0.95 for s in sel)]
        best = None
        for j in range(p):
            if j in sel or any(A[j, s] >= 0.6 for s in sel): continue
            base = sel + adj(j); pj = pv(fit(base + [j]), fit(base))
            if best is None or pj < best[0]: best = (pj, j)
        if best is None or best[0] > gates[min(step, 3)]: break
        j = best[1]
        clus = [k for k in range(p) if A[j, k] >= 0.6 and k not in sel and not any(A[k, s] >= 0.6 for s in sel)]
        if len(clus) > 1:
            ll = {k: fit(sel + [k]) for k in clus}; top = max(ll.values())
            cand = [k for k in clus if ll[k] >= top - 2]
            j = max(cand, key=lambda k: np.sum(C[k, clus] ** 2))
        sel.append(j)
    changed = True
    while changed and sel:
        changed = False
        for j in list(sel):
            rest = [s for s in sel if s != j]
            if pv(fit(sel), fit(rest)) > 0.05 / p: sel.remove(j); changed = True; break
    # product / square screen with score prescreen
    r0 = y - y.mean(); scores = []
    for a in range(p):
        for b in range(a, p):
            if a != b and A[a, b] >= 0.6: continue
            z = X[:, a] * X[:, b]; z = z - z.mean()
            scores.append((float((z @ r0) ** 2 / (z @ z + 1e-9)), a, b))
    scores.sort(reverse=True); npair = p * (p + 1) / 2; prods = []
    for _, a, b in scores[:15]:
        base = sel + [k for k in dict.fromkeys([a, b]) if k not in sel]
        if pv(fit(base + [(a, b)]), fit(base)) < 0.002 / npair: prods.append((a, b))
        if len(prods) == 2: break
    drivers = list(sel)
    for a, b in prods:
        for k in (a, b):
            if k not in drivers: drivers.append(k)
    drivers = drivers[:MAX_DRIVERS]
    cols = list(drivers)
    if drivers:
        cols += [h for h in hubs if h not in cols and all(A[h, d] < 0.95 for d in cols)]
    return Design(drivers=tuple(ids[j] for j in drivers), columns=tuple(ids[j] for j in cols),
                  products=tuple((ids[a], ids[b]) for a, b in prods), loadings={})

